{
  "implementation": "def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    distances = case["distances"]
    edges = []
    for a, b, d in distances:
        w = max(core[a], core[b], d)
        if a <= b:
            edges.append((a, b, w))
        else:
            edges.append((b, a, w))
    edges.sort(key=lambda e: (e[2], e[0], e[1]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            xr, yr = yr, xr
        parent[yr] = xr
        if rank[xr] == rank[yr]:
            rank[xr] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for a, b, w in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Graph is disconnected; MST cannot be formed.")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
